[CmdletBinding()]
param()
$ErrorActionPreference = 'Stop'; Set-StrictMode -Version Latest
$integrator = Join-Path $PSScriptRoot 'integrate-admin-module.ps1'; $bootstrap = Join-Path $PSScriptRoot 'new-consumer.ps1'; $generator = Join-Path $PSScriptRoot 'new-admin-module.ps1'
$tooling = Split-Path -Parent (Split-Path -Parent $PSScriptRoot); $root = Join-Path ([IO.Path]::GetTempPath()) ('hoc-h4-04-' + [guid]::NewGuid().ToString('N'))
function Assert([bool]$ok,[string]$message){if(-not $ok){throw $message}}
function Bytes([string]$p){return ,([IO.File]::ReadAllBytes($p))}
function Fixture([string]$name){$p=Join-Path $root $name;& $bootstrap -SourceRoot $tooling -SourceSha 6a8605a63d18d35767f520d57d33193f6d15aa29 -OutputRoot $p -ApplicationId ContosoAdmin -RootUrl https://localhost:44320 -Apply|Out-Null;& $generator -ConsumerRoot $p -ApplicationId ContosoAdmin -ModuleName Products -EntityName Product -RouteSegment products -Apply|Out-Null;return $p}
function Expect-Failure([string]$name,[scriptblock]$action,[string]$reason){$failed=$false;try{&$action}catch{$failed=$true;Assert ($_.Exception.Message -like "*$reason*") "$name failed for wrong reason: $($_.Exception.Message)"};Assert $failed "$name unexpectedly succeeded."}
function Targets([string]$p){@('ContosoAdmin.slnx','src/ContosoAdmin.Web/ContosoAdmin.Web.csproj','src/ContosoAdmin.Web/ContosoAdminWebModule.cs','src/ContosoAdmin.EntityFrameworkCore/ContosoAdmin.EntityFrameworkCore.csproj','src/ContosoAdmin.EntityFrameworkCore/EntityFrameworkCore/ContosoAdminEntityFrameworkCoreModule.cs','src/ContosoAdmin.EntityFrameworkCore/EntityFrameworkCore/ContosoAdminDbContext.cs')|ForEach-Object{Join-Path $p $_}}
function Snapshot([string[]]$files){$s=@{};foreach($f in $files){$s[$f]=Bytes $f};return $s}
function Assert-Same([hashtable]$before){foreach($f in $before.Keys){Assert ([Linq.Enumerable]::SequenceEqual[byte]($before[$f],(Bytes $f))) "Unexpected mutation: $f"}}
try {
 New-Item -ItemType Directory -Path $root|Out-Null
 $valid=Fixture valid;$targets=Targets $valid;$before=Snapshot $targets
 & $integrator -ConsumerRoot $valid -ApplicationId ContosoAdmin -ModuleName Products -EntityName Product;Assert-Same $before
 & $integrator -ConsumerRoot $valid -ApplicationId ContosoAdmin -ModuleName Products -EntityName Product -Apply;$after=Snapshot $targets
 & $integrator -ConsumerRoot $valid -ApplicationId ContosoAdmin -ModuleName Products -EntityName Product -Apply;Assert-Same $after
 $conflict=Fixture conflict;$targets=Targets $conflict;$before=Snapshot $targets;$db=Join-Path $conflict 'src/ContosoAdmin.EntityFrameworkCore/EntityFrameworkCore/ContosoAdminDbContext.cs';Add-Content $db '    public DbSet<Other> Products { get; set; }';$before=Snapshot $targets;Expect-Failure 'conflicting DbSet' {& $integrator -ConsumerRoot $conflict -ApplicationId ContosoAdmin -ModuleName Products -EntityName Product -Apply} "DbSet property 'Products' conflicts";Assert-Same $before
 $comments=Fixture comments;$targets=Targets $comments;$web=Join-Path $comments 'src/ContosoAdmin.Web/ContosoAdminWebModule.cs';Add-Content $web '// typeof(ProductsWebModule)';$db=Join-Path $comments 'src/ContosoAdmin.EntityFrameworkCore/EntityFrameworkCore/ContosoAdminDbContext.cs';Add-Content $db '// builder.ConfigureProducts();';& $integrator -ConsumerRoot $comments -ApplicationId ContosoAdmin -ModuleName Products -EntityName Product -Apply;$webText=Get-Content -Raw $web;$dbText=Get-Content -Raw $db;Assert (([regex]::Matches($webText,'(?m)^\s*typeof\(ProductsWebModule\)')).Count -eq 1) 'Comment-only module dependency was accepted.';Assert (([regex]::Matches($dbText,'(?m)^\s*builder\.ConfigureProducts\(\);')).Count -eq 1) 'Comment-only model call was accepted.'
 $partial=Fixture partial;$targets=Targets $partial;& $integrator -ConsumerRoot $partial -ApplicationId ContosoAdmin -ModuleName Products -EntityName Product -Apply;& $integrator -ConsumerRoot $partial -ApplicationId ContosoAdmin -ModuleName Products -EntityName Product -Apply;Assert (([regex]::Matches((Get-Content -Raw (Join-Path $partial 'src/ContosoAdmin.EntityFrameworkCore/EntityFrameworkCore/ContosoAdminDbContext.cs')),'DbSet<Product> Products')).Count -eq 1) 'Consistent partial/idempotent DbSet duplicated.'
 $fault=Fixture fault;$targets=Targets $fault;$before=Snapshot $targets;Expect-Failure 'fault rollback' {& $integrator -ConsumerRoot $fault -ApplicationId ContosoAdmin -ModuleName Products -EntityName Product -Apply -TestFailAfterWrites 3} 'Test fault injected';Assert-Same $before
 $reparse=Fixture reparse;$targets=Targets $reparse;$before=Snapshot $targets;$module=Join-Path $reparse 'modules';$outside=Join-Path $root 'outside';Move-Item $module $outside;New-Item -ItemType Junction -Path $module -Target $outside|Out-Null;Expect-Failure 'module junction' {& $integrator -ConsumerRoot $reparse -ApplicationId ContosoAdmin -ModuleName Products -EntityName Product -Apply} 'ancestor must not be a symbolic link or reparse point';Assert-Same $before
 Write-Host 'H4-04 integration self-tests passed.'
} finally {if(Test-Path $root){Remove-Item -LiteralPath $root -Recurse -Force}}
